SELECT r.* FROM repair_order r
JOIN equipment e ON e.id = r.equipment_id
JOIN lab l ON l.id = e.lab_id
WHERE r.deleted = 0
AND r.reporter_id = #{reporterId}
AND l.admin_id = #{managerId} AND l.deleted = 0
AND r.equipment_id = #{query.equipmentId}
AND e.lab_id = #{query.labId}
AND r.status = #{query.status}
ORDER BY r.create_time DESC, r.id DESC

SELECT COUNT(*) FROM repair_order r
JOIN equipment e ON e.id = r.equipment_id
JOIN lab l ON l.id = e.lab_id
WHERE r.deleted = 0 AND r.image_url = #{imageUrl}
  AND (r.reporter_id = #{reporterId}
    OR (l.admin_id = #{managerId} AND l.deleted = 0)
  )

mapper.update:
UPDATE usage_log SET end_time = #{now}, update_time = #{now}, remark = '设备故障，使用提前结束'
WHERE deleted = 0 AND end_time IS NULL AND reservation_id IN (
    SELECT id FROM reservation WHERE equipment_id = #{equipmentId}
      AND deleted = 0 AND status IN (0, 1) AND sign_in_time IS NOT NULL AND end_time > #{now}
)
